const PromptMatcherSchema = z.union([
  z.string().min(1),
  z.object({ name: z.string().min(1) }),
  z.object({ regex: z.string().min(1), flags: z.string().default('') }),
]);

const PresetAdapterOptionSchema = z
  .object({
    id: z.string().min(1),
    label: z.string().min(1),
    description: z.string().default(''),
    type: z.enum(['between']).optional(),
    match: z
      .object({
        below: z.string(),
        above: z.string(),
      })
      .optional(),
    enable: z.array(PromptMatcherSchema).default([]),
    disable: z.array(PromptMatcherSchema).default([]),
    requires_any: z.array(z.object({ group_id: z.string().min(1), option_id: z.string().min(1) })).default([]),
    on_enable: z
      .object({
        enable: z.array(PromptMatcherSchema).default([]),
        disable: z.array(PromptMatcherSchema).default([]),
      })
      .optional(),
    tool_output: z.object({ enabled_tool: z.string().min(1), disabled_tool: z.string().min(1) }).optional(),
    effect: z
      .array(z.string().trim().min(1))
      .default([])
      .transform(effects => [...new Set(effects)]),
  })
  .superRefine((option, context) => {
    if (option.type === 'between' && !option.match) {
      context.addIssue({
        code: 'custom',
        path: ['match'],
        message: 'type 为 between 时必须填写 match.below 和 match.above',
      });
    }
  });

const VariableInputOptionSchema = z
  .object({
    id: z.string().min(1).optional(),
    label: z.string().min(1),
    description: z.string().default(''),
    type: z.enum(['var_input', 'global_var_input']),
    variable_id: z.string().trim().min(1),
  })
  .transform(option => ({
    ...option,
    id: option.id ?? `${option.type}:${option.variable_id}`,
  }));

