  function scanCurrentSummaryMessages() {
    const config_result = readAdapterConfig();
    const regexes = config_result.config.summary.generation.detect_regexes;
    if (regexes.length === 0) {
      toastr.error('未配置总结识别正则，无法手动扫描。', SCRIPT_NAME);
      return;
    }

    const { compiled, errors: regex_errors } = compileSummaryRegexes(regexes);
    if (compiled.length === 0) {
      toastr.error(`没有可用的总结识别正则：\n${regex_errors.join('\n')}`, SCRIPT_NAME);
      return;
    }

    const messages = readCurrentChatMessages();
    const matched_ids = messages
      .filter(message => isCompiledSummaryRegexMatched(message.message, compiled))
      .map(message => message.message_id);
    let added_count = 0;
    matched_ids.forEach(message_id => {
      if (addSummaryMessageId(message_id)) {
        added_count += 1;
      }
    });
    refreshSummaryState();

    const warning =
      regex_errors.length > 0 ? `\n有 ${regex_errors.length} 条正则无效：\n${regex_errors.slice(0, 3).join('\n')}` : '';
    toastr.success(
      `扫描完成：共扫描 ${messages.length} 层，命中 ${matched_ids.length} 层，新增 ${added_count} 个总结书签。${warning}`,
      SCRIPT_NAME,
    );
  }

  async function runManualSummary() {
    if (is_applying.value) {
      return;
    }

    const state = loadState();
    refreshSummaryState();
    if (!summary_state.value.has_chat) {
      toastr.error('需要先打开一个聊天。', SCRIPT_NAME);
      return;
    }
    if (state.errors.length > 0 || !state.preset) {
      toastr.error('配置存在错误，无法开始总结。', SCRIPT_NAME);
      return;
    }

    const status = buildSummaryGenerationStatus(state.config, state.groups);
    if (!status.can_start) {
      toastr.error(`总结使用设置不可用：\n${status.errors.join('\n')}`, SCRIPT_NAME);
      return;
    }
    if (summary_settings.value.content_handling === 'worldbook' && !getChatWorldbookName('current')) {
      toastr.error('当前聊天没有绑定世界书，无法使用“放置于世界书”。', SCRIPT_NAME);
      return;
    }

    const settings_snapshot = cloneJson(summary_settings.value);
    let summary_prompt: string | undefined;
    try {
      summary_prompt = await requestManualSummaryPrompt(settings_snapshot);
    } catch (error) {
      notifySummaryError(settings_snapshot.manual_prompt_enabled ? '输入总结需求' : '总结确认弹窗', error);
      return;
    }
    if (summary_prompt === undefined) {
      return;
    }

    if (isHostGenerationInProgress()) {
      toastr.warning('当前已有普通回复正在生成，请稍后重试。', SCRIPT_NAME);
      return;
    }

    const group_config = state.config.groups.find(group => group.id === status.group_id);
    const group_view = state.groups.find(group => group.id === status.group_id);
    const option_view = findSummaryOption(group_view, status.option_id);
    if (!group_config || !group_view || !option_view) {
      toastr.error('总结使用设置已失效，请刷新后重试。', SCRIPT_NAME);
      return;
    }

    const target_states = buildOptionTargetStates(group_config, group_view, option_view, true);
    const effect_target_states = buildOptionEffectTargetStates(group_config, group_view, option_view, true);
    if (target_states.size === 0 && effect_target_states.size === 0) {
      toastr.error('总结使用选项没有命中任何提示词或 effect。', SCRIPT_NAME);
      return;
    }

    manual_summary_running.value = true;
    is_applying.value = true;
    try {
      let generated_message_id: number | undefined;
      let generation_failed = false;
      let restore_failed = false;
      let generation_stage = '切换总结预设';
      const snapshot = getGroupPromptStateSnapshot(state.preset, group_view);
      const effect_snapshot = getGroupEffectStateSnapshot(group_view);
      try {
        const preset = getPreset('in_use');
        const changed = applyPromptTargetStates(preset, target_states);
        if (changed) {
          await replacePreset('in_use', preset, { render: 'immediate' });
        }
        notifyEffectErrors(applyEffectTargetStates(effect_target_states).errors);

        generation_stage = '发送总结需求';
        const before_request_message_id = getLastMessageId();
        await createChatMessages([{ message: summary_prompt, role: 'user' }], { refresh: 'affected' });
        const before_last_message_id = getLastMessageId();
        if (before_last_message_id <= before_request_message_id) {
          throw new Error('发送总结需求后没有检测到新的用户楼层。');
        }

        generation_stage = '总结生成';
        await Promise.resolve(SillyTavern.generate('normal'));
        const latest_message = getChatMessages(-1)[0];
        if (latest_message && latest_message.message_id > before_last_message_id) {
          generated_message_id = latest_message.message_id;
        }
      } catch (error) {
        generation_failed = true;
        notifySummaryError(generation_stage, error, {
          group_id: status.group_id,
          manual_prompt_enabled: settings_snapshot.manual_prompt_enabled,
          option_id: status.option_id,
          option: status.option_label,
        });
      } finally {
        try {
          await restorePromptStateSnapshot(snapshot);
        } catch (error) {
          restore_failed = true;
          notifySummaryError('恢复总结预设状态', error, {
            group_id: status.group_id,
            option_id: status.option_id,
            option: status.option_label,
          });
        } finally {
          restoreEffectStateSnapshot(effect_snapshot);
        }
      }

      if (generation_failed || restore_failed) {
        return;
      }
      if (generated_message_id === undefined) {
        toastr.warning('生成结束，但没有检测到新的总结楼层。', SCRIPT_NAME);
        return;
      }

      const generated_message = getChatMessages(generated_message_id)[0];
      if (!generated_message) {
        toastr.warning(`生成结束，但第 ${generated_message_id} 层已不存在。`, SCRIPT_NAME);
        return;
      }

      try {
        addSummaryMessageId(generated_message_id);
        await processGeneratedSummaryMessage(generated_message_id, generated_message.message, settings_snapshot);
        toastr.success(`已完成第 ${generated_message_id} 层总结。`, SCRIPT_NAME);
      } catch (error) {
        notifySummaryError('总结后处理', error, {
          content_handling: settings_snapshot.content_handling,
          generated_message_id,
          auto_hide_after_manual: settings_snapshot.hide_rules.auto_hide_after_manual,
          hide_summary: settings_snapshot.hide_rules.hide_summary,
        });
      }
    } catch (error) {
      notifySummaryError('手动总结流程', error, {
        group_id: status.group_id,
        option_id: status.option_id,
        option: status.option_label,
      });
    } finally {
      manual_summary_running.value = false;
      is_applying.value = false;
      refresh();
    }
  }

  async function startManualSummary() {
    if (manual_summary_task) {
      await manual_summary_task;
      return;
    }

    const task = runManualSummary();
    manual_summary_task = task;
    try {
      await task;
    } finally {
      if (manual_summary_task === task) {
        manual_summary_task = undefined;
      }
    }
  }

  async function runSummaryRegeneration() {
    if (is_applying.value) {
      return;
    }

    const state = loadState();
    refreshSummaryState();
    const regeneration_status = summary_regeneration_status.value;
    if (!regeneration_status.can_start || regeneration_status.message_id === undefined) {
      toastr.error(regeneration_status.reason || '当前无法重新总结。', SCRIPT_NAME);
      return;
    }
    if (isHostGenerationInProgress()) {
      toastr.warning('当前已有普通回复正在生成，请稍后重试。', SCRIPT_NAME);
      return;
    }

    const message_id = regeneration_status.message_id;
    const confirmed = await confirmAction(
      `确认重新总结第 ${message_id} 层吗？将生成一个新的总结版本，当前版本会保留，之后仍可通过左右箭头切换查看。生成期间会临时调整可见楼层。`,
    );
    if (!confirmed) {
      return;
    }

    const status = buildSummaryGenerationStatus(state.config, state.groups);
    const group_config = state.config.groups.find(group => group.id === status.group_id);
    const group_view = state.groups.find(group => group.id === status.group_id);
    const option_view = findSummaryOption(group_view, status.option_id);
    if (!state.preset || !status.can_start || !group_config || !group_view || !option_view) {
      toastr.error('总结使用设置已失效，请刷新后重试。', SCRIPT_NAME);
      return;
    }

    const target_states = buildOptionTargetStates(group_config, group_view, option_view, true);
    const effect_target_states = buildOptionEffectTargetStates(group_config, group_view, option_view, true);
    if (target_states.size === 0 && effect_target_states.size === 0) {
      toastr.error('总结使用选项没有命中任何提示词或 effect。', SCRIPT_NAME);
      return;
    }

    const settings_snapshot = cloneJson(summary_settings.value);
    const visibility_snapshot = captureSummaryVisibilitySnapshot();
    const swipe_snapshot = captureSummarySwipeSnapshot(message_id);
    if (!swipe_snapshot) {
      toastr.error(`无法读取第 ${message_id} 层的现有总结版本。`, SCRIPT_NAME);
      return;
    }

    const prompt_snapshot = getGroupPromptStateSnapshot(state.preset, group_view);
    const effect_snapshot = getGroupEffectStateSnapshot(group_view);
    const ignored_summary_ids = new Set([message_id]);
    let generated_content: string | undefined;
    let generation_error: unknown;
    let restore_error: unknown;
    let generation_stage = '准备重新总结';

    manual_summary_running.value = true;
    is_applying.value = true;
    try {
      try {
        await applySummaryHideRules(settings_snapshot, true, {
          ignored_summary_ids,
          sync_when_scope_missing: true,
        });

        generation_stage = '切换总结预设';
        const preset = getPreset('in_use');
        const changed = applyPromptTargetStates(preset, target_states);
        if (changed) {
          await replacePreset('in_use', preset, { render: 'immediate' });
        }
        notifyEffectErrors(applyEffectTargetStates(effect_target_states).errors);

        generation_stage = '生成新的总结版本';
        await Promise.resolve(SillyTavern.generate('swipe'));
        const generated_swiped = getChatMessages(message_id, { include_swipes: true })[0];
        const generated_message = getChatMessages(message_id)[0];
        const has_new_version =
          generated_swiped &&
          (generated_swiped.swipes.length > swipe_snapshot.swipes.length ||
            generated_swiped.swipe_id !== swipe_snapshot.swipe_id);
        if (!has_new_version || !generated_message) {
          throw new Error('生成结束，但没有检测到新的总结版本。');
        }
        generated_content = generated_message.message;
      } catch (error) {
        generation_error = error;
      } finally {
        try {
          await restorePromptStateSnapshot(prompt_snapshot);
        } catch (error) {
          restore_error = error;
        } finally {
          restoreEffectStateSnapshot(effect_snapshot);
        }
      }

      if (generation_error || restore_error || generated_content === undefined) {
        try {
          await restoreSummarySwipeSnapshot(swipe_snapshot);
          await restoreSummaryVisibilitySnapshot(visibility_snapshot);
        } catch (error) {
          notifySummaryError('恢复重新总结前的状态', error, { message_id });
        }
        notifySummaryError(
          restore_error ? '恢复总结预设状态' : generation_stage,
          restore_error ?? generation_error ?? new Error('没有生成新的总结版本。'),
          { group_id: status.group_id, message_id, option_id: status.option_id },
        );
        return;
      }

      try {
        await restoreSummaryVisibilitySnapshot(visibility_snapshot);
        addSummaryMessageId(message_id);
        await processGeneratedSummaryMessage(message_id, generated_content, settings_snapshot, {
          replace_existing: true,
        });
        toastr.success(`第 ${message_id} 层已生成新的总结版本，原版本仍然保留。`, SCRIPT_NAME);
      } catch (error) {
        try {
          await restoreSummaryVisibilitySnapshot(visibility_snapshot);
        } catch (visibility_error) {
          console.error(`[${SCRIPT_NAME}] 恢复重新总结前的楼层状态失败。`, visibility_error);
        }
        toastr.warning('总结已生成，但后处理失败', SCRIPT_NAME, { extendedTimeOut: 15000, timeOut: 8000 });
        console.error(`[${SCRIPT_NAME}] 重新总结后处理失败。`, { error, message_id });
      }
    } catch (error) {
      try {
        await restoreSummarySwipeSnapshot(swipe_snapshot);
        await restoreSummaryVisibilitySnapshot(visibility_snapshot);
      } catch (restore_failure) {
        console.error(`[${SCRIPT_NAME}] 恢复重新总结前的状态失败。`, restore_failure);
      }
      notifySummaryError('重新总结流程', error, { message_id });
    } finally {
      manual_summary_running.value = false;
      is_applying.value = false;
      refresh();
    }
  }

  async function regenerateSummary() {
    if (manual_summary_task) {
      await manual_summary_task;
      return;
    }

    const task = runSummaryRegeneration();
    manual_summary_task = task;
    try {
      await task;
    } finally {
      if (manual_summary_task === task) {
        manual_summary_task = undefined;
      }
    }
  }

  function selectDebugRecord(id: string) {
    selected_debug_record_id.value = id;
  }

  async function clearDebugRecords() {
    const api = debug_api;
    if (!api) {
      return;
    }
    try {
      await Promise.resolve(api.clearRecords());
    } catch (error) {
      toastr.error(`清空 Debug 记录失败：${normalizeError(error)}`, SCRIPT_NAME);
      console.error(`[${SCRIPT_NAME}] 清空 Debug 记录失败。`, error);
    }
  }

  async function getDebugContent(record_id: string, content_id: string): Promise<string | undefined> {
    const api = debug_api;
    if (!api) {
      return undefined;
    }
    return await Promise.resolve(api.getContent(record_id, content_id));
  }

  function pruneSelectedExportKeys() {
    const valid_keys = new Set<string>();
    groups.value.forEach(group => {
      group.options.forEach(option => {
        if (option.exportable) {
          valid_keys.add(getExportOptionKey(group.id, option.id));
        }
      });
    });
    selected_export_keys.value = new Set([...selected_export_keys.value].filter(key => valid_keys.has(key)));
  }

  function loadState(): LoadedState {
    refreshSelectionLibrary();
    refreshUiPreferences();
    refreshSummarySettings();
    const config_result = readAdapterConfig();
    config.value = config_result.config;
    title.value = config_result.config.title;
    description.value = config_result.config.description;
    loaded_preset_name.value = getLoadedPresetName();

    let preset: Preset | undefined;
    try {
      preset = getPreset('in_use');
    } catch (error) {
      const message = `读取当前使用预设失败：${normalizeError(error)}`;
      console.warn(`[${SCRIPT_NAME}] ${message}`, error);
      groups.value = [];
      blocking_errors.value = [...config_result.errors, message];
      errors.value = blocking_errors.value;
      refreshSummaryState();
      return { config: config_result.config, groups: [], errors: blocking_errors.value };
    }

    const built = buildGroupViews(config_result.config, preset);
    groups.value = orderGroupViews(built.groups, ui_preferences.value.group_order);
    const has_unsupported_reasoner_format_check = built.groups.some(group =>
      group.reasoner_format_checks.some(check => check.disabled),
    );
    if (has_unsupported_reasoner_format_check && !reasoner_format_unsupported_notified) {
      reasoner_format_unsupported_notified = true;
      toastr.error('当前酒馆版本不支持一键设置模型思考格式化，请升级后重试。', SCRIPT_NAME);
    }
    pruneSelectedExportKeys();
    blocking_errors.value = [...config_result.errors, ...built.errors];
    errors.value = [...blocking_errors.value, ...built.option_errors];
    refreshSummaryState();
    return { config: config_result.config, preset, groups: built.groups, errors: blocking_errors.value };
  }

  function refresh() {
    loadState();
    refreshDebugApi();
  }

  function startExportMode() {
    loadState();
    if (errors.value.length > 0) {
      toastr.error('配置存在错误，无法进入导出模式。', SCRIPT_NAME);
      return;
    }
    review_panel.value = undefined;
    organizing.value = false;
    export_mode.value = true;
    selected_export_keys.value = new Set();
  }

  function cancelExportMode() {
    review_panel.value = undefined;
    export_mode.value = false;
    selected_export_keys.value = new Set();
  }

  function closeReviewPanel() {
    if (is_applying.value) return;
    review_panel.value = undefined;
  }

  function isExportOptionSelected(group_id: string, option_id: string): boolean {
    return selected_export_keys.value.has(getExportOptionKey(group_id, option_id));
  }

  function toggleExportOption(group_id: string, option_id: string) {
    const option = groups.value
      .find(group => group.id === group_id)
      ?.options.find(candidate => candidate.id === option_id);
    if (!option?.exportable) {
      toastr.warning('只有动态匹配选项可以导出。', SCRIPT_NAME);
      return;
    }

    const key = getExportOptionKey(group_id, option_id);
    const next_keys = new Set(selected_export_keys.value);
    if (next_keys.has(key)) {
      next_keys.delete(key);
    } else {
      next_keys.add(key);
    }
    selected_export_keys.value = next_keys;
  }

  function exportSelectedOptions() {
    const state = loadState();
    if (state.errors.length > 0 || !state.preset) {
      toastr.error('配置存在错误，无法导出。', SCRIPT_NAME);
      return;
    }

    const selected_keys = selected_export_keys.value;
    const items: ExportFile['items'] = [];
    const review_items: ReviewPromptItem[] = [];
    for (const group of state.groups) {
      for (const option of group.options) {
        if (!option.export_source || !selected_keys.has(getExportOptionKey(group.id, option.id))) {
          continue;
        }

        const prompt = state.preset.prompts[option.export_source.prompt_index];
        if (!prompt) {
          continue;
        }

        const source: ExportFile['items'][number] = {
          group_id: option.export_source.group_id,
          match_id: option.export_source.match_id,
          name: prompt.name,
          prompt: cloneJson(prompt),
        };
        const item_index = items.length;
        items.push(source);
        review_items.push({
          key: getReviewItemKey(source.group_id, source.match_id, source.name, item_index),
          group_id: source.group_id,
          group_label: group.label,
          match_id: source.match_id,
          name: source.name,
          action: 'export',
          action_label: '导出',
          preview: getPromptPreview(source.prompt),
          source,
        });
      }
    }

    if (items.length === 0) {
      toastr.warning('请先勾选要导出的动态匹配选项。', SCRIPT_NAME);
      return;
    }

    const file: ExportFile = {
      type: EXPORT_FILE_TYPE,
      version: EXPORT_FILE_VERSION,
      exported_at: new Date().toISOString(),
      title: state.config.title,
      items,
    };
    review_panel.value = {
      kind: 'export',
      title: `确认导出 ${items.length} 项设置`,
      filename: getExportFilename(state.config.title),
      file,
      items: review_items,
    };
  }

  function confirmExportReview() {
    const panel = review_panel.value;
    if (panel?.kind !== 'export') {
      return;
    }

    downloadJson(panel.filename, panel.file);
    toastr.success(`已导出 ${panel.items.length} 项设置。`, SCRIPT_NAME);
    cancelExportMode();
  }

  function stageSettingsImport(file: ExportFile, source_name: string, source_warnings: string[] = []) {
    const state = loadState();
    if (state.errors.length > 0 || !state.preset) throw new Error('当前预设配置不可用');
    const review = buildImportReview(file, state.config, state.preset);
    if (file.items.length === 0 && source_warnings.length === 0) throw new Error('没有可导入的设置项');
    organizing.value = false;
    export_mode.value = false;
    selected_export_keys.value = new Set();
    review_panel.value = {
      kind: 'import',
      title: '选择要导入的内容',
      file,
      ...review,
      source_name,
      source_warnings,
      target_name: getLoadedPresetName(),
      target_context: importTargetContext(state.config, state.preset),
      selected_keys: review.items.filter(item => item.action === 'create').map(item => item.key),
    };
  }

  async function importPresetSettings(text: string, filename = '设置文件'): Promise<void> {
    if (is_applying.value) return;
    try {
      const parsed = ExportFileSchema.parse(JSON.parse(text));
      stageSettingsImport(parsed, filename);
    } catch (error) {
      toastr.error('导入文件无效：' + normalizeError(error), SCRIPT_NAME);
    }
  }

  function getImportPresetNames(): string[] {
    try {
      return getPresetNames().filter(name => name !== 'in_use');
    } catch (error) {
      toastr.error('读取预设列表失败：' + normalizeError(error), SCRIPT_NAME);
      return [];
    }
  }

  function importFromPreset(preset_name: string): boolean {
    if (is_applying.value) return false;
    try {
      if (!getImportPresetNames().includes(preset_name)) throw new Error('来源预设已不存在');
      const current = readAdapterConfig();
      if (current.errors.length > 0) throw new Error('当前解析配置不可用');
      const source = getPreset(preset_name);
      const items: ExportFile['items'] = [];
      const warnings: string[] = [];
      for (const group of current.config.groups) {
        const resolved = resolveGroupOptions(group, source);
        warnings.push(...resolved.errors.map(error => group.label + '：' + error));
        for (const option of resolved.options) {
          if (!option.export_source) {
            if (option.id.endsWith(':between-unmatched')) warnings.push(group.label + '：' + option.description);
            continue;
          }
          const prompt = source.prompts[option.export_source.prompt_index];
          if (prompt)
            items.push({
              group_id: group.id,
              match_id: option.export_source.match_id,
              name: prompt.name,
              prompt: cloneJson(prompt),
            });
        }
      }
      stageSettingsImport(
        { type: EXPORT_FILE_TYPE, version: EXPORT_FILE_VERSION, title: preset_name, items },
        preset_name,
        [...new Set(warnings)],
      );
      return true;
    } catch (error) {
      toastr.error('解析预设失败：' + normalizeError(error), SCRIPT_NAME);
      return false;
    }
  }

  function setImportSelection(keys: string[], checked: boolean) {
    const panel = review_panel.value;
    if (panel?.kind !== 'import' || is_applying.value) return;
    const valid = new Set(
      [...panel.items, ...panel.failed_items.filter(item => item.can_append)].map(item => item.key),
    );
    const selected = new Set(panel.selected_keys);
    keys.filter(key => valid.has(key)).forEach(key => (checked ? selected.add(key) : selected.delete(key)));
    panel.selected_keys = [...selected];
  }

  async function confirmImportReview(): Promise<void> {
    const panel = review_panel.value;
    if (panel?.kind !== 'import' || is_applying.value || panel.selected_keys.length === 0) return;
    is_applying.value = true;
    try {
      const state = loadState();
      if (state.errors.length > 0 || !state.preset) throw new Error('当前预设配置不可用');
      if (getLoadedPresetName() !== panel.target_name) {
        review_panel.value = undefined;
        throw new Error('目标酒馆预设已切换，请重新选择导入来源');
      }
      const context = importTargetContext(state.config, state.preset);
      const review = buildImportReview(panel.file, state.config, state.preset);
      if (context !== panel.target_context) {
        const previous_actions = new Map([
          ...panel.items.map(item => [item.key, item.action] as const),
          ...panel.failed_items.filter(item => item.can_append).map(item => [item.key, 'append'] as const),
        ]);
        const selected = new Set(panel.selected_keys);
        const candidates = [
          ...review.items.map(item => ({ key: item.key, action: item.action })),
          ...review.failed_items.filter(item => item.can_append).map(item => ({ key: item.key, action: 'append' })),
        ];
        review_panel.value = {
          ...panel,
          ...review,
          target_context: context,
          selected_keys: candidates
            .filter(item => selected.has(item.key) && previous_actions.get(item.key) === item.action)
            .map(item => item.key),
        };
        toastr.warning('目标内容或解析规则已变化，已更新预览，请重新确认。', SCRIPT_NAME);
        return;
      }
      const selected = new Set(panel.selected_keys);
      let created_count = 0;
      let overwritten_count = 0;
      let appended_count = 0;
      for (const item of review.items.filter(item => selected.has(item.key))) {
        const result = applyImportItem(state.preset, state.config, item.source);
        if ('error' in result) throw new Error(result.error);
        if (result.action === 'create') created_count += 1;
        else overwritten_count += 1;
      }
      for (const item of review.failed_items.filter(item => item.can_append && selected.has(item.key))) {
        appendImportItem(state.preset, item.source);
        appended_count += 1;
      }
      if (created_count + overwritten_count + appended_count === 0) throw new Error('请勾选要导入的内容');
      await replacePreset('in_use', state.preset, { render: 'immediate' });
      if (getLoadedPresetName() !== panel.target_name) throw new Error('目标预设已切换，未保存到命名预设');
      await replacePreset(panel.target_name, state.preset, { render: 'none' });
      review_panel.value = undefined;
      refresh();
      toastr.success(
        '已导入并保存：新增 ' +
          created_count +
          ' 项，覆盖 ' +
          overwritten_count +
          ' 项，追加 ' +
          appended_count +
          ' 项。',
        SCRIPT_NAME,
      );
    } catch (error) {
      toastr.error('导入失败：' + normalizeError(error), SCRIPT_NAME);
    } finally {
      is_applying.value = false;
    }
  }

  async function applyReasonerFormatCheck(group_id: string, check_id: string): Promise<void> {
    if (is_applying.value) {
      return;
    }

    const check = groups.value
      .find(group => group.id === group_id)
      ?.reasoner_format_checks.find(candidate => candidate.id === check_id);
    if (!check) {
      toastr.error('没有找到模型思考格式化检查项。', SCRIPT_NAME);
      return;
    }
    if (check.disabled) {
      toastr.error(REASONER_FORMAT_UNSUPPORTED, SCRIPT_NAME);
      return;
    }

    is_applying.value = true;
    try {
      const context = getReasonerHostContext();
      const manager = getReasoningPresetManager(context);
      const reasoning = context.powerUserSettings?.reasoning as ReasoningSettings | undefined;
      if (!manager || !reasoning) {
        toastr.error(REASONER_FORMAT_UNSUPPORTED, SCRIPT_NAME);
        return;
      }

      await manager.savePreset(REASONER_FORMAT_PRESET_NAME, {
        name: REASONER_FORMAT_PRESET_NAME,
        prefix: REASONER_FORMAT_PREFIX,
        suffix: REASONER_FORMAT_SUFFIX,
        separator: '',
      });
      reasoning.auto_parse = true;
      $('#reasoning_auto_parse').prop('checked', true);
      await Promise.resolve(context.saveSettingsDebounced());

      if (!readReasonerFormatStatus().satisfied) {
        throw new Error('酒馆未应用预期的推理格式化设置');
      }

      loadState();
      toastr.success(`已设置并启用“${REASONER_FORMAT_PRESET_NAME}”。`, SCRIPT_NAME);
    } catch (error) {
      console.error(`[${SCRIPT_NAME}] 设置模型思考格式化失败。`, error);
      toastr.error(`设置模型思考格式化失败：${normalizeError(error)}`, SCRIPT_NAME);
    } finally {
      is_applying.value = false;
    }
  }

  async function applyOption(group_id: string, option_id: string): Promise<void> {
    if (is_applying.value) {
      return;
    }

    is_applying.value = true;
    try {
      const state = loadState();
      if (state.errors.length > 0 || !state.preset) {
        toastr.error('配置存在错误，未修改预设。', SCRIPT_NAME);
        return;
      }

      const group_config = state.config.groups.find(group => group.id === group_id);
      const group_view = state.groups.find(group => group.id === group_id);
      const option_view = group_view?.options.find(option => option.id === option_id);
      if (!group_config || !group_view || !option_view) {
        toastr.error('没有找到要应用的选项。', SCRIPT_NAME);
        return;
      }
      if (!option_view.selection_available || !option_view.requirements_met) {
        toastr.warning(option_view.matched_summary, SCRIPT_NAME);
        return;
      }

      const target_states = buildOptionTargetStates(group_config, group_view, option_view, false);
      const effect_target_states = buildOptionEffectTargetStates(group_config, group_view, option_view, false);
      applyOptionRequirementTargets(state.config, state.preset, target_states, effect_target_states);
      checkToolOutputSupport(
        state.config,
        state.preset,
        effect_target_states.get(GEMINI_TOOL_OUTPUT_EFFECT_ID) ?? getGeminiToolOutputModeApi()?.getEnabled() ?? false,
      );
      if (target_states.size === 0 && effect_target_states.size === 0) {
        toastr.warning('该选项没有命中任何提示词或 effect。', SCRIPT_NAME);
        return;
      }

      const prompt_changed = applyPromptTargetStates(state.preset, target_states);
      if (prompt_changed) {
        await replacePreset('in_use', state.preset, { render: 'immediate' });
      }

      const effect_result = applyEffectTargetStates(effect_target_states);
      notifyEffectErrors(effect_result.errors);
      if (effect_result.errors.length === 0) {
        syncToolOutputOptions(state.config, state.preset);
        if (prompt_changed || effect_result.changed) {
          toastr.success(`已应用“${option_view.label}”。`, SCRIPT_NAME);
        } else {
          toastr.info('当前预设已经符合该选项。', SCRIPT_NAME);
        }
      }
      refresh();
    } catch (error) {
      toastr.error(`应用选项失败：${normalizeError(error)}`, SCRIPT_NAME);
      refresh();
    } finally {
      is_applying.value = false;
    }
  }

